1	package org.jsoup.safety;
2	
3	import org.jsoup.internal.StringUtil;
4	import org.jsoup.nodes.Element;
5	import org.jsoup.parser.Parser;
6	
7	/**
8	 Parses and sanitizes the text of an allowed {@code <style>} element, one stylesheet rule at a time. Like
9	 {@link StyleCleaner}, it is a small hand scanner rather than a full CSS parser: each scope (the whole sheet, or an
10	 at-rule block) is split into qualified rules ({@code selector { declarations }}) and statements ({@code @import …},
11	 {@code @media …}) while tracking the actual nesting of strings, parentheses, block comments, and CSS backslash
12	 escapes, so punctuation inside strings, functions, or comments cannot break out of its rule or declaration. A
13	 brace at the top level of a scope always bounds a block (a brace inside a balanced function does not), and a '}'
14	 after an unclosed function is honored as the recovery boundary, so the malformed declaration invalidates only
15	 itself and never swallows the rules after the block. Nested blocks (rules inside an {@code @media}/
16	 {@code @supports} block) are handled recursively and independently.
17	
18	 <p>Selectors, at-rule preludes, ordinary declaration names and values (numbers, colors, fonts, custom
19	 properties), whitespace, comments, and duplicates are emitted verbatim in source order. {@code @import}
20	 references, every {@code url(…)} argument (including one nested inside another function), and the legacy
21	 {@code expression(…)} function are checked with the same URL policy and the same obfuscation handling (mixed
22	 case, HTML entities, percent-encoding, control bytes, and CSS escapes) as an inline {@code style} attribute. The
23	 HTML parser keeps {@code <style>} contents as raw text and never applies HTML entities to it, so rule and
24	 declaration boundaries are always scanned in the raw text (an entity such as {@code &#123;} cannot forge a block
25	 boundary), while entities within an already bounded statement or declaration are decoded only for the safety
26	 decision; a surviving fragment always keeps its original spelling.</p>
27	
28	 <p>A rejected import or declaration takes only itself; its rule's surviving selectors and declarations are kept,
29	 and no safe content in the same rule is lost. Unclosed strings, parentheses, or comments, repeated separators, and
30	 truncated imports and nested references never throw: rules whose boundaries can still be determined are handled
31	 independently, and only the unbounded or undecidable fragment is discarded. When no rule survives the result is
32	 empty, in which case the caller removes the {@code <style>} element.</p>
33	
34	 <p>The cleaner is stateless and thread-safe; all per-sheet state lives on the local parse stack.</p>
35	 */
36	final class StyleSheetCleaner {
37	    // bound recursion so a deliberately or accidentally deep nesting cannot exhaust a small (e.g. virtual-thread)
38	    // stack; this matches the parser's own max depth and is far beyond any realistically authored stylesheet
39	    private static final int MaxNesting = 512;
40	
41	    private final StyleCleaner sc;
42	
43	    private StyleSheetCleaner(Safelist safelist, String tagName, Element el) {
44	        this.sc = StyleCleaner.create(safelist, tagName, el);
45	    }
46	
47	    /**
48	     Cleans the raw text of an allowed {@code <style>} element rule by rule, preserving the order and original
49	     spelling of every rule, declaration, and value that survives.
50	     @return the cleaned stylesheet text, or {@code null} when no rule survives (in which case the element is removed)
51	     */
52	    static String clean(Safelist safelist, String tagName, Element el, String css) {
53	        return new StyleSheetCleaner(safelist, tagName, el).cleanSheet(css);
54	    }
55	
56	    private String cleanSheet(String css) {
57	        if (StringUtil.isBlank(css)) return css; // no rules at all: keep the element as-is
58	        int[] match = sc.parenMatches(css); // every parenthesis's mate, computed once and shared by every scope
59	        int[] opens = new int[css.length()]; // the per-scope open stack; block boundaries always reset its depth
60	        StringBuilder out = StringUtil.borrowBuilder();
61	        process(css, 0, css.length(), 0, match, opens, out);
62	        return out.length() == 0 ? null : StringUtil.releaseBuilder(out);
63	    }
64	
65	    /**
66	     Walks one stylesheet scope (the whole sheet, or an at-rule block) and appends every surviving statement and
67	     rule to {@code out} in source order. A parenthesis closes a function only when its mate lies within the
68	     scope, so a semicolon stays function content only for a function that closes before the block ends.
69	     */
70	    private void process(String css, int start, int end, int depth, int[] match, int[] opens, StringBuilder out) {
71	        int parenDepth = 0;
72	        int ruleStart = start;
73	        int i = start;
74	        while (i < end) {
75	            char c = css.charAt(i);
76	            if (c == '\\') { // CSS escape: the next code unit is literal, even '\{' or '\;'
77	                i += 2;
78	                continue;
79	            }
80	            if (c == '"' || c == '\'') {
81	                int[] quote = sc.scanQuoted(css, i + 1, c);
82	                i = quote[1] == 1 ? quote[0] + 1 : quote[0]; // recover at a newline/';', else run to scope end
83	                continue;
84	            }
85	            if (c == '/' && i + 1 < end && css.charAt(i + 1) == '*') {
86	                int close = css.indexOf("*/", i + 2);
87	                // a closer beyond this scope cannot close the comment inside it: a CSS comment runs to EOF, so the
88	                // comment and everything after it in this scope is an unbounded fragment. The statement accumulated
89	                // before the comment still has a determinable boundary and is validated on its own merits; a later
90	                // scope (after the block's real '}') is unaffected and parses independently.
91	                if (close < 0 || close >= end) {
92	                    emitStatement(css, ruleStart, i, false, out);
93	                    ruleStart = end;
94	                    i = end;
95	                } else {
96	                    i = close + 2;
97	                }
98	                continue;
99	            }
100	            if (c == '(') {
101	                opens[parenDepth++] = i;
102	            } else if (c == ')') {
103	                if (parenDepth > 0) parenDepth--; // a stray ')' outside any function is ordinary separator text
104	            } else if (c == '{' && parenDepth == 0) {
105	                int close = matchingBrace(css, i + 1, end, match, opens);
106	                int bodyEnd = close >= 0 ? close : end;
107	                emitRule(css, ruleStart, i, bodyEnd, depth, match, opens, out);
108	                parenDepth = 0; // braces always bound blocks; an unclosed function does not carry into the next rule
109	                ruleStart = close >= 0 ? close + 1 : end;
110	                i = ruleStart;
111	                continue;
112	            } else if (c == '}' && parenDepth == 0) {
113	                // a stray '}' closes no block opened in this scope: this is a CSS parse error and the unfinished
114	                // statement accumulated before it (whitespace and comments included, since a comment-only fragment
115	                // would not survive a re-clean on its own) is discarded rather than glued onto the next surviving
116	                // statement, which would change its meaning and fail to re-clean. The following rules, whose
117	                // boundaries can still be determined, parse independently.
118	                parenDepth = 0;
119	                ruleStart = i + 1;
120	            }
121	            // a '{' or '}' inside an unclosed function is ordinary (invalid) declaration text: block boundaries are
122	            // established by matchingBrace, which honors '}' so the function cannot swallow the following rules
123	            else if (c == ';' && (parenDepth == 0 || match[opens[parenDepth - 1]] < 0
124	                || match[opens[parenDepth - 1]] >= end)) {
125	                // a ';' ends the statement unless it is content of a function that closes later in this scope
126	                emitStatement(css, ruleStart, i, true, out);
127	                parenDepth = 0;
128	                ruleStart = i + 1;
129	            }
130	            i++;
131	        }
132	        if (ruleStart < end) emitStatement(css, ruleStart, end, false, out); // a trailing statement without ';'
133	    }
134	
135	    /**
136	     Validates and emits one qualified rule (or at-rule block): the prelude is copied verbatim when it carries no
137	     unsafe reference, and the block is emitted only when its body yields surviving content. Nested blocks are
138	     processed into their own buffer first, so an empty body never leaves an empty rule behind.
139	     */
140	    private void emitRule(String css, int preludeStart, int brace, int bodyEnd, int depth, int[] match, int[] opens,
141	                          StringBuilder out) {
142	        int p = sc.skipSpaceAndComments(css, preludeStart, brace);
143	        if (p < 0 || p >= brace) return; // an unterminated comment or an empty prelude (a stray '{') is not a rule
144	        if (!preludeIsSafe(css, p, brace)) return;
145	        StringBuilder body = StringUtil.borrowBuilder();
146	        // every block body is walked as a rule scope: nested rules (@media/@supports) recurse, and declarations
147	        // (@font-face/@page, or a qualified rule's contents) validate as declarations
148	        if (depth < MaxNesting) process(css, brace + 1, bodyEnd, depth + 1, match, opens, body);
149	        if (body.length() == 0) {
150	            StringUtil.releaseBuilderVoid(body);
151	            return;
152	        }
153	        out.append(css, preludeStart, brace + 1); // selector/at-rule prelude and the opening brace, verbatim
154	        out.append(body);
155	        StringUtil.releaseBuilderVoid(body);
156	        // a block whose '}' was lost (e.g. swallowed by an unterminated comment) is closed here, exactly as a
157	        // browser closes it at EOF, so the output never carries an orphan opening brace and stays idempotent. When
158	        // the body ends with an unescaped run of backslashes, one added '}' would itself be CSS-escaped and fail to
159	        // close the block; add a second '}' the run cannot consume.
160	        int slashes = 0;
161	        for (int b = out.length() - 1; b >= 0 && out.charAt(b) == '\\'; b--) slashes++;
162	        out.append('}');
163	        if (slashes % 2 == 1) out.append('}');
164	    }
165	
166	    /**
167	     A selector/at-rule prelude is inert text except for an actual reference it may carry. The leading at-keyword
168	     of an at-rule prelude ({@code @media}, {@code @supports}) is skipped, since an '@' cannot start a declaration
169	     value; the remainder is checked like an ordinary declaration value.
170	     */
171	    private boolean preludeIsSafe(String css, int start, int end) {
172	        String raw = css.substring(start, end);
173	        String check = raw.indexOf('&') >= 0 ? Parser.unescapeEntities(raw, false) : raw;
174	        int len = check.length();
175	        int s = sc.skipSpaceAndComments(check, 0, len);
176	        if (s < 0 || s >= len) return false;
177	        if (check.charAt(s) == '@') {
178	            StringBuilder atName = new StringBuilder();
179	            int nameEnd = sc.scanIdent(check, s + 1, len, atName);
180	            if (nameEnd == s + 1) return false; // a bare '@' is not an at-rule
181	            s = sc.skipSeparators(check, nameEnd, len);
182	            if (s < 0 || s >= len) return true; // an at-keyword with no prelude condition
183	        }
184	        return sc.referencesAreSafe(check, s, len);
185	    }
186	
187	    /**
188	     Validates and emits one top-level statement between separators. Whitespace- or comment-only fragments are
189	     skipped; an {@code @import}'s reference must pass the URL rules, any other at-statement passes when its own
190	     references pass, and a declaration-shaped statement passes the same declaration rules as an inline
191	     {@code style} attribute (so the legacy script-entry properties are denied everywhere). A surviving statement
192	     keeps its source spelling, and the source semicolon that terminated it ({@code terminated}) is emitted so
193	     adjacent statements stay separated; a block- or EOF-bounded statement gains none.
194	     */
195	    private void emitStatement(String css, int start, int end, boolean terminated, StringBuilder out) {
196	        int p = sc.skipSpaceAndComments(css, start, end);
197	        if (p < 0 || p >= end) return; // an unterminated comment makes the statement unbounded
198	        int q = end;
199	        while (q > p && StyleCleaner.isCssSpace(css.charAt(q - 1))) q--;
200	        if (p == q) return;
201	        String raw = css.substring(start, q);
202	        String check = raw.indexOf('&') >= 0 ? Parser.unescapeEntities(raw, false) : raw;
203	        int len = check.length();
204	        int s = sc.skipSpaceAndComments(check, 0, len);
205	        if (s < 0 || s >= len) return;
206	        boolean safe;
207	        int keptEnd = q; // source end of the surviving text (usually the whole trimmed statement)
208	        if (check.charAt(s) == '@') {
209	            StringBuilder atName = new StringBuilder();
210	            int nameEnd = sc.scanIdent(check, s + 1, len, atName);
211	            if (nameEnd == s + 1) return; // a bare '@' is not an at-rule
212	            if (atName.toString().equalsIgnoreCase("import")) {
213	                safe = sc.isSafeImportDeclaration(check, s, len);
214	            } else {
215	                // other at-statements (@charset, @namespace, an unknown prelude): skip the at-keyword, then check
216	                // the remainder like an ordinary value
217	                int r = sc.skipSeparators(check, nameEnd, len);
218	                safe = r >= 0 && (r >= len || sc.referencesAreSafe(check, r, len));
219	            }
220	        } else {
221	            // a declaration-shaped statement (including the contents of an @font-face/@page block)
222	            int to = sc.safeDeclarationRange(check, 0, len, false);
223	            safe = to > 0;
224	            if (safe && check == raw) keptEnd = start + to; // trim exactly as the inline cleaner would
225	        }
226	        if (safe) {
227	            out.append(css, start, keptEnd);
228	            if (terminated) {
229	                // when the surviving text ends with an unescaped run of backslashes, an added ';' would itself be
230	                // CSS-escaped and glue this statement to the next one on a re-clean; a single space consumes the
231	                // escape so the separator stays a separator
232	                int slashes = 0;
233	                for (int b = out.length() - 1; b >= 0 && out.charAt(b) == '\\'; b--) slashes++;
234	                if (slashes % 2 == 1) out.append(' ');
235	                out.append(';');
236	            }
237	        }
238	    }
239	
240	    /**
241	     Finds the '}' that closes a block, skipping strings, comments, escapes, parentheses, and nested braces. A '{'
242	     inside a balanced function never starts a nested block, and a '}' inside a balanced function never closes the
243	     outer block; but a '}' after an unclosed '(' (a function whose ')' is missing within the scope) is honored as
244	     the block boundary, the same parse-error recovery a browser performs, so the malformed declaration invalidates
245	     only itself and the following rules still parse independently.
246	     */
247	    private int matchingBrace(String css, int from, int end, int[] match, int[] opens) {
248	        int braceDepth = 1;
249	        int parenDepth = 0;
250	        int i = from;
251	        while (i < end) {
252	            char c = css.charAt(i);
253	            if (c == '\\') { i += 2; continue; }
254	            if (c == '"' || c == '\'') {
255	                int[] quote = sc.scanQuoted(css, i + 1, c);
256	                i = quote[1] == 1 ? quote[0] + 1 : quote[0]; // closed quote, or recovery at a newline/';'/EOF
257	                continue;
258	            }
259	            if (c == '/' && i + 1 < end && css.charAt(i + 1) == '*') {
260	                int close = css.indexOf("*/", i + 2);
261	                if (close < 0 || close >= end) return -1;
262	                i = close + 2;
263	                continue;
264	            }
265	            if (c == '(') {
266	                opens[parenDepth++] = i;
267	            } else if (c == ')') {
268	                if (parenDepth > 0) parenDepth--;
269	            } else if (parenDepth == 0 && c == '{') {
270	                braceDepth++;
271	            } else if (c == '}') {
272	                // a '}' bounds the block only when the innermost '(' is closed within the scope; otherwise the
273	                // function is unclosed and this '}' is the browser-style recovery point
274	                int open = parenDepth > 0 ? opens[parenDepth - 1] : -1;
275	                boolean insideClosedFunction = open >= 0 && match[open] >= 0 && match[open] < end;
276	                if (!insideClosedFunction) {
277	                    braceDepth--;
278	                    if (braceDepth == 0) return i;
279	                }
280	            }
281	            i++;
282	        }
283	        return -1;
284	    }
285	}
