8	/**
9	 Parses and sanitizes the inline CSS of an element's {@code style} attribute, one declaration at a time. The parser is
10	 a small hand scanner rather than a full CSS parser: declarations are split on semicolons while tracking the actual
11	 nesting of strings, parentheses, block comments, and CSS backslash escapes, so that punctuation inside strings
12	 ({@code font-family: 'Calibri;'}) or functions ({@code background: url(/img;a.png)}) cannot break out of its
13	 declaration.
14	
15	 <p>Declarations with no recognizable property, an unclosed function or string (recovered only at a newline, per the
16	 CSS bad-string rule), unbalanced parentheses, or a forbidden or unverifiable external reference are dropped
17	 individually; surrounding safe declarations, other attributes, and the element's text are untouched. An unclosed
18	 comment is itself an unbounded fragment and is dropped, but scanning recovers at the next semicolon so that later
19	 declarations are still parsed independently. Comment text and the contents of ordinary quoted strings are emitted
20	 verbatim but are inert as CSS — a browser removes comments and never tokenizes a function call out of a string — so
21	 a {@code url(...)}-shaped fragment inside either does not by itself trigger a URL check (a quoted string is still
22	 checked when it is the actual argument of a real {@code url()} call). Function names are read with full CSS escape
23	 semantics (hex runs such as {@code \75 rl}, single-character escapes such as a backslash before the letter u, and consecutive
24	 backslashes), so an escaped or differently cased {@code url}, {@code expression}, or equivalent reference is
25	 normalized before the safelist's URL rules are applied. Repeated separators and other degenerate input never throw
26	 and never cause following declarations to be joined into a rejected value.</p>
27	
28	 <p>The cleaner is stateless and thread-safe; all per-value state lives on the local parse stack.</p>
29	 */
30	final class StyleCleaner {
31	    private final Safelist safelist;
32	    private final String tagName;
33	    private final Element el;
34	
35	    private StyleCleaner(Safelist safelist, String tagName, Element el) {
36	        this.safelist = safelist;
37	        this.tagName = tagName;
38	        this.el = el;
39	    }
40	
41	    /**
42	     Creates a cleaner bound to the given element. The {@code style} attribute cleaner and the {@code <style>}
43	     element stylesheet cleaner ({@link StyleSheetCleaner}) share the same lexical primitives and URL policy.
44	     */
45	    static StyleCleaner create(Safelist safelist, String tagName, Element el) {
46	        return new StyleCleaner(safelist, tagName, el);
47	    }
48	
49	    /**
50	     Cleans an inline {@code style} attribute value declaration by declaration, preserving the order and original
51	     text of every declaration that survives.
52	     @return the cleaned value, or {@code null} when no declaration survives (in which case the attribute is removed)
53	     */
54	    static String clean(Safelist safelist, String tagName, Element el, String value) {
55	        return new StyleCleaner(safelist, tagName, el).clean(value);
56	    }
57	
58	    private String clean(String value) {
59	        StringBuilder out = StringUtil.borrowBuilder();
60	        int length = value.length();
61	        int[] match = parenMatches(value); // index of each parenthesis's mate, or -1 when unmatched
62	        int[] opens = new int[length]; // positions of the currently open parentheses
63	        int segStart = 0;
64	        int parenDepth = 0;
65	        boolean segmentBad = false; // this segment already contains a malformed construct
66	        int i = 0;
67	        while (i < length) {
68	            char c = value.charAt(i);
69	            if (c == '\\') { // CSS escape: the next code unit is literal, even '\;' or '\"'
70	                i += 2;
71	                continue;
72	            }
73	            if (c == '"' || c == '\'') {
74	                int[] quote = scanQuoted(value, i + 1, c);
75	                if (quote[1] == 1) {
76	                    i = quote[0] + 1;
77	                } else {
78	                    segmentBad = true; // a bad-string token makes only this declaration malformed
79	                    i = quote[1] == 2 ? quote[0] + 1 : quote[0]; // recover at the newline, or at the next ';'
80	                }
81	                continue;
82	            }
83	            if (c == '/' && i + 1 < length && value.charAt(i + 1) == '*') {
84	                int close = value.indexOf("*/", i + 2);
85	                if (close < 0) {
86	                    // an unterminated comment cannot be bounded and so invalidates only its own fragment: recover at
87	                    // the next ';' so that following declarations stay independently parseable. When no ';' remains,
88	                    // the text before the comment is still validated on its own merits.
89	                    int semi = value.indexOf(';', i + 2);
90	                    if (semi < 0) {
91	                        appendSafeDeclaration(value, segStart, i, segmentBad || parenDepth != 0, out);
92	                        segStart = length;
93	                        break;
94	                    }
95	                    segmentBad = true;
96	                    i = semi; // the ';' branch ends the malformed fragment and resets for the next declaration
97	                    continue;
98	                }
99	                i = close + 2;
100	                continue;
101	            }
102	            if (c == '(') {
103	                opens[parenDepth++] = i;
104	            } else if (c == ')') {
105	                if (parenDepth > 0) parenDepth--;
106	                else segmentBad = true; // a stray ')' makes this declaration malformed
107	            } else if (c == ';') {
108	                if (parenDepth > 0 && match[opens[parenDepth - 1]] >= 0) {
109	                    // the ';' is content of a function that closes later (e.g. an unquoted data: URL); keep scanning
110	                    i++;
111	                    continue;
112	                }
113	                // otherwise end here; a function that never closes only invalidates this declaration
114	                appendSafeDeclaration(value, segStart, i, segmentBad || parenDepth != 0, out);
115	                segStart = i + 1;
116	                segmentBad = false;
117	                parenDepth = 0;
118	            }
119	            i++;
120	        }
121	        if (segStart < length) appendSafeDeclaration(value, segStart, length, segmentBad || parenDepth != 0, out);
122	
123	        if (out.length() == 0) {
124	            StringUtil.releaseBuilderVoid(out);
125	            return null;
126	        }
127	        return StringUtil.releaseBuilder(out);
128	    }
129	
130	    /**
131	     Computes the matching parenthesis of every balanced {@code (} and {@code )} in the value, applying the same
132	     * lexical rules (escapes, quoted strings with bad-string recovery, and comments) as the declaration walk. An
133	     * unmatched parenthesis maps to {@code -1}; a single linear pass keeps style cleaning O(n) even when a value
134	     * contains many semicolons nested in functions.
135	     */
136	    int[] parenMatches(String value) {
137	        int length = value.length();
138	        int[] match = new int[length];
139	        Arrays.fill(match, -1);
140	        int[] stack = new int[length];
141	        int depth = 0;
142	        int i = 0;
143	        while (i < length) {
144	            char c = value.charAt(i);
145	            if (c == '\\') { i += 2; continue; }
146	            if (c == '"' || c == '\'') {
147	                int[] quote = scanQuoted(value, i + 1, c);
148	                i = quote[1] == 0 ? quote[0] : quote[0] + 1; // at the recovered ';', or past the quote/newline
149	                continue;
150	            }
151	            if (c == '/' && i + 1 < length && value.charAt(i + 1) == '*') {
152	                int close = value.indexOf("*/", i + 2);
153	                if (close < 0) {
154	                    // mirror the declaration walk: an unterminated comment invalidates only its own fragment, and
155	                    // scanning recovers at the next ';'. Any parentheses opened in that dropped fragment are
156	                    // abandoned there, so the nesting depth resets with it.
157	                    int semi = value.indexOf(';', i + 2);
158	                    if (semi < 0) break;
159	                    depth = 0;
160	                    i = semi;
161	                    continue;
162	                }
163	                i = close + 2;
164	                continue;
165	            }
166	            if (c == '(') {
167	                stack[depth++] = i;
168	            } else if (c == ')') {
169	                if (depth > 0) {
170	                    int open = stack[--depth];
171	                    match[open] = i;
172	                    match[i] = open;
173	                }
174	            }
175	            i++;
176	        }
177	        return match;
178	    }
179	
180	    /**
181	     * <ul>
182	     *   <li>state {@code 1}: the closing quote was found at {@code end};</li>
183	     *   <li>state {@code 2}: the string was recovered at the newline at {@code end} (the CSS bad-string rule; later
184	     *       declarations stay independently parseable);</li>
185	     *   <li>state {@code 0}: neither quote nor newline remains; {@code end} is the index of the first semicolon at
186	     *       or after the opening quote (the malformed declaration is cut there), or the value length when none.</li>
187	     * </ul>
188	     */
189	    int[] scanQuoted(String value, int from, char quote) {
190	        int length = value.length();
191	        int firstSemi = -1;
192	        for (int i = from; i < length; i++) {
193	            char c = value.charAt(i);
194	            if (c == '\\') { i++; continue; }
195	            if (c == quote) return new int[] {i, 1};
196	            if (c == '\n' || c == '\r') return new int[] {i, 2}; // bad-string recovery at a CSS newline
197	            if (c == ';' && firstSemi < 0) firstSemi = i;
198	        }
199	        return new int[] {firstSemi >= 0 ? firstSemi : length, 0};
200	    }
201	
202	    /**
203	     Validates the declaration at {@code [start, end)} and, when safe, appends its verbatim text to {@code out}.
204	     @param structurallyBad the containing walk already found a malformed construct (a bad-string token)
205	     */
206	    private void appendSafeDeclaration(String value, int start, int end, boolean structurallyBad, StringBuilder out) {
207	        int to = safeDeclarationRange(value, start, end, structurallyBad);
208	        if (to > start) append(out, value, start, to);
209	    }
210	
211	    /**
212	     Validates the declaration at {@code [start, end)} the same way an inline {@code style} attribute declaration
213	     is validated, and returns the end index (up to {@code end}, with trailing whitespace trimmed) of the verbatim
214	     source span that survives, or {@code start} when the whole declaration must be dropped. The stylesheet cleaner
215	     reuses this for every declaration inside a rule body, while emitting the surrounding rule text itself.
216	     @param structurallyBad the containing walk already found a malformed construct (a bad-string token)
217	     */
218	    int safeDeclarationRange(String value, int start, int end, boolean structurallyBad) {
219	        if (structurallyBad) return start;
220	        int p = skipSpaceAndComments(value, start, end);
221	        if (p < 0) return start; // an unterminated leading comment rejects only this declaration
222	        int q = end;
223	        while (q > p && isCssSpace(value.charAt(q - 1))) q--;
224	        if (p == q) return start; // whitespace-only fragment, e.g. from a duplicated ';'
225	        int nameStart = p;
226	
227	        // an at-rule in a declaration position: only @import is meaningful inline, and its reference must pass
228	        if (value.charAt(p) == '@') {
229	            return isSafeImportDeclaration(value, p, q) ? q : start;
230	        }
231	        // property: a plain CSS identifier (including a vendor prefix such as -webkit-*) or a custom property
232	        // (--name). Escapes, comments, and quotes are not accepted in a declaration name.
233	        boolean custom = false;
234	        if (value.charAt(p) == '-') {
235	            if (p + 1 < end && value.charAt(p + 1) == '-') {
236	                p += 2;
237	                custom = true;
238	                if (p >= q || !isIdentChar(value.charAt(p))) return start; // "--" alone is not a property name
239	                while (p < q && isIdentChar(value.charAt(p))) p++;
240	            } else {
241	                if (p + 1 >= q || !isIdentStart(value.charAt(p + 1))) return start; // a bare '-' is not a property name
242	                p++; // let the ordinary identifier run consume the vendor-prefixed remainder
243	            }
244	        }
245	        if (!custom) {
246	            if (p >= q || !isIdentStart(value.charAt(p))) return start; // no property name
247	            do { p++; } while (p < q && isIdentChar(value.charAt(p)));
248	        }
249	        int afterName = skipSpaceAndComments(value, p, q); // whitespace/comments may sit between the name and the ':'
250	        if (afterName < 0) return start; // an unterminated or unsafe comment in the gap rejects only this declaration
251	        if (afterName >= q || value.charAt(afterName) != ':') return start; // no ':' (empty fragment, junk, duplicate ';')
252	        p = afterName + 1; // step past ':'
253	
254	        if (isDangerousProperty(value, nameStart)) return start; // known script-entry properties, regardless of value
255	        // a custom property (--name) holds arbitrary free text: its value is scanned as one string, so a colon that is
256	        // not part of a reference (e.g. "--x: https://example.com" or a time such as "12:00"), a stray quote, or an
257	        // at-keyword other than @import is preserved verbatim; only its references decide its fate
258	        boolean safe = custom
259	            ? freeTextIsSafe(value.substring(p, q))
260	            : referencesAreSafe(value, p, q);
261	        return safe ? q : start;
262	    }
263	
264	    /** Appends a surviving declaration, separated from any earlier ones by a single semicolon. */
265	    private void append(StringBuilder out, String value, int from, int to) {
266	        if (out.length() > 0) out.append(';');
267	        out.append(value, from, to);
268	    }
269	
270	    /**
271	     Validates an entire {@code @import} statement: its leading reference (a quoted URL or a {@code url(...)}) must
272	     * pass the URL rules, and any trailing layer/media/supports conditions must themselves contain no unsafe
273	     * reference.
274	     */
275	    boolean isSafeImportDeclaration(String value, int at, int end) {
276	        int i = at + 1;
277	        StringBuilder atName = new StringBuilder();
278	        i = scanIdent(value, i, end, atName);
279	        if (!atName.toString().equalsIgnoreCase("import")) return false;
280	        int sep = skipSeparators(value, i, end);
281	        if (sep < 0 || sep >= end) return false;
282	        i = sep;
283	        int afterRef;
284	        char c = value.charAt(i);
285	        if (c == '"' || c == '\'') {
286	            int[] quote = scanQuoted(value, i + 1, c);
287	            if (quote[1] != 1) return false;
288	            if (!safelist.isSafeStyleUrl(tagName, el, unescape(value.substring(i + 1, quote[0])))) return false;
289	            afterRef = quote[0] + 1;
290	        } else if (isIdentStart(c) || c == '-' || c == '\\') {
291	            StringBuilder fnName = new StringBuilder();
292	            int nameEnd = scanIdent(value, i, end, fnName);
293	            int k = skipSeparators(value, nameEnd, end);
294	            if (k < 0 || k >= end || value.charAt(k) != '(' || !fnName.toString().equalsIgnoreCase("url")) return false;
295	            int argEnd = matchingParen(value, k + 1, end);
296	            if (argEnd < 0 || !isSafeUrlArgument(value, k + 1, argEnd)) return false;
297	            afterRef = argEnd + 1;
298	        } else {
299	            return false;
300	        }
301	        return referencesAreSafe(value, afterRef, end);
302	    }
303	
304	    /**
305	     Advances past CSS whitespace and complete block comments. A comment is inert token separators (a browser removes
306	     it before tokenization), so its text is never inspected for a concealed reference; an unterminated comment is
307	     still an unbounded fragment and yields {@code -1}, rejecting only the declaration that contains it.
308	     */
309	    int skipSpaceAndComments(String value, int i, int end) {
310	        while (i < end) {
311	            char c = value.charAt(i);
312	            if (isCssSpace(c)) { i++; continue; }
313	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
314	                int close = value.indexOf("*/", i + 2);
315	                if (close < 0 || close >= end) return -1;
316	                i = close + 2;
317	                continue;
318	            }
319	            break;
320	        }
321	        return i;
322	    }
323	
324	    /** Whitespace and comments may separate a function name from its opening parenthesis ({@code url /**\/ ( ... )}). */
325	    int skipSeparators(String value, int i, int end) {
326	        return skipSpaceAndComments(value, i, end);
327	    }
328	
329	    /**
330	     Tests whether a comment-only separator (no whitespace) from {@code nameEnd} glues the preceding identifier run
331	     to another identifier run that is itself followed (optionally via separators) by {@code (}. A comment wedged
332	     between two identifier runs ({@code ur/**\/l( ... )} or {@code expr/**\/ession( ... )}) does not join them under
333	     a strict CSS tokenizer, but a lenient engine could read the glued run as a single function token; such a
334	     declaration is rejected rather than risk a split {@code url} or {@code expression} escaping recognition. Real
335	     whitespace keeps the runs distinct tokens, and two bare runs without a following call ({@code a/**\/b}) stay
336	     untouched. The second run is read with full escape semantics so that an escaped continuation such as
337	     {@code ur/**\/\6c( ... )} is just as ambiguous.
338	     */
339	    private boolean commentGluesIdentToCall(String value, int nameEnd, int end) {
340	        int i = nameEnd;
341	        boolean sawComment = false;
342	        while (i < end) {
343	            char c = value.charAt(i);
344	            if (isCssSpace(c)) return false; // real whitespace keeps the two runs distinct tokens
345	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
346	                int close = value.indexOf("*/", i + 2);
347	                if (close < 0 || close > end) return false;
348	                sawComment = true;
349	                i = close + 2;
350	                continue;
351	            }
352	            break; // reached the start of whatever the separator abuts
353	        }
354	        if (!sawComment) return false;
355	        if (i >= end || !(isIdentStart(value.charAt(i)) || value.charAt(i) == '\\'))
356	            return false; // the separator must glue onto another identifier run
357	        StringBuilder glued = new StringBuilder();
358	        int k = scanIdent(value, i, end, glued);
359	        k = skipSeparators(value, k, end);
360	        return k >= 0 && k < end && value.charAt(k) == '(';
361	    }
362	
363	    /**
364	     Denies the legacy script-entry properties that load executable or behavior-bound content even through an
365	     * otherwise allowed-looking {@code url(...)}: {@code -moz-binding} (XBL) and IE's {@code behavior}. The name is
366	     * the plain identifier run starting at {@code nameStart}; a comment appended to the name cannot change the
367	     * comparison.
368	     */
369	    private boolean isDangerousProperty(String value, int nameStart) {
370	        int p = nameStart;
371	        while (p < value.length() && isIdentChar(value.charAt(p))) p++;
372	        String name = value.substring(nameStart, p);
373	        return name.equalsIgnoreCase("-moz-binding") || name.equalsIgnoreCase("behavior");
374	    }
375	
376	    /**
377	     Walks a declaration value in a single lexical pass: strings, comments, escapes, and balanced functions are
378	     recognized exactly as in declaration splitting. Block comments and the contents of ordinary quoted strings are
379	     inert token separators (their text is emitted verbatim but never fetched or tokenized as a call); a quoted
380	     string is still checked when it is the actual argument of a {@code url()} call. Every {@code url(...)}
381	     argument, an {@code @import} reference, and the legacy {@code expression(...)} function is read with full CSS
382	     escape semantics, so a hex or character escape, consecutive backslashes, or a case change in the function name
383	     ({@code \75 rl(...)}, a backslash-escaped {@code URL}, {@code \65 xpression(...)}) reaches the same decision as the plain
384	     spelling. Unbalanced parentheses, an unterminated string or comment, or any failed reference check rejects the
385	     declaration.
386	     */
387	    boolean referencesAreSafe(String value, int start, int end) {
388	        int parenDepth = 0;
389	        int i = start;
390	        while (i < end) {
391	            char c = value.charAt(i);
392	            if (c == '"' || c == '\'') {
393	                int[] quote = scanQuoted(value, i + 1, c);
394	                if (quote[1] != 1) return false; // no bad-string recovery inside a value being checked
395	                // an identifier run glued directly to the string and followed by a call (e.g. u"rl"(...)) is a
396	                // syntax error a strict browser discards but a lenient one could read as one escaped function name
397	                if (stringGluesIdentToCall(value, i, quote[0], end)) return false;
398	                // ordinary string content is inert: it is never fetched as a reference (a quoted url() argument is
399	                // checked separately by isSafeUrlArgument)
400	                i = quote[0] + 1;
401	                continue;
402	            }
403	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
404	                int close = value.indexOf("*/", i + 2);
405	                if (close < 0 || close >= end) return false; // unterminated comment within the declaration
406	                i = close + 2; // comment text is inert token separators, never a concealed declaration or call
407	                continue;
408	            }
409	            if (c == '(') { parenDepth++; i++; continue; }
410	            if (c == ')') {
411	                if (parenDepth == 0) return false; // unmatched ')'
412	                parenDepth--;
413	                i++;
414	                continue;
415	            }
416	            if (c == '@') return false; // no at-rule (e.g. a buried @import) is valid inside a declaration value
417	            if (isIdentStart(c) || c == '-' || c == '\\') {
418	                StringBuilder decoded = new StringBuilder();
419	                int nameEnd = scanIdent(value, i, end, decoded);
420	                String fnName = decoded.toString();
421	                int j = skipSeparators(value, nameEnd, end);
422	                if (j < 0) return false; // an unterminated comment after the name rejects the declaration
423	                if (commentGluesIdentToCall(value, nameEnd, end)) return false; // e.g. ur/**/l(...)
424	                if (j < end && value.charAt(j) == '(') {
425	                    int argEnd = matchingParen(value, j + 1, end);
426	                    if (argEnd < 0) return false;
427	                    // a function name whose escapes decode to punctuation (e.g. "l\;expression") is not a real CSS
428	                    // function token; reject rather than risk it being read as two tokens by a quirky engine
429	                    if (!isPlainName(fnName)) return false;
430	                    if (fnName.equalsIgnoreCase("expression")) return false; // legacy JScript entry point
431	                    if (fnName.equalsIgnoreCase("url") && !isSafeUrlArgument(value, j + 1, argEnd)) return false;
432	                    i = j; // resume at '(' so a nested url()/expression() inside the arguments is also checked
433	                    continue;
434	                }
435	                i = nameEnd;
436	                continue;
437	            }
438	            i++;
439	        }
440	        return parenDepth == 0;
441	    }
442	
443	    /** Tests that a function name is a plain identifier, with no escape that decoded to punctuation or whitespace. */
444	    private static boolean isPlainName(String name) {
445	        int length = name.length();
446	        if (length == 0) return false;
447	        for (int k = 0; k < length; k++) {
448	            char c = name.charAt(k);
449	            boolean ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
450	                || (c >= '0' && c <= '9') || c == '-' || c == '_';
451	            if (!ok) return false;
452	        }
453	        return true;
454	    }
455	
456	    /**
457	     Reads a CSS identifier token starting at {@code from} with full escape semantics: plain identifier characters
458	     (including a leading run of dashes), single-character escapes (a backslash before any character such as u or '(', or a doubled
459	     {@code \\}), and hex escapes ({@code \75}, up to six hex digits) together with the single whitespace
460	     delimiter that may follow one ({@code \75 rl} is therefore one token, exactly as a browser reads it). The
461	     decoded code points are appended to {@code decoded}, and the index just past the token is returned. The decoded
462	     form is what a function name is compared against, so a hex-escaped, character-escaped, doubled-backslash, or
463	     differently cased {@code url} or {@code expression} cannot hide from the reference checks.
464	     */
465	    int scanIdent(String value, int from, int end, StringBuilder decoded) {
466	        int i = from;
467	        while (i < end) {
468	            char c = value.charAt(i);
469	            if (c == '\\') {
470	                int[] escape = consumeEscape(value, i, end);
471	                if (escape[1] >= 0) decoded.appendCodePoint(escape[1]);
472	                i = escape[0];
473	                continue;
474	            }
475	            if (isIdentChar(c)) { decoded.append(c); i++; continue; }
476	            break;
477	        }
478	        return i;
479	    }
480	
481	    /**
482	     Consumes one CSS escape sequence beginning at the backslash {@code i}. Returns {@code [next, codePoint]}:
483	     {@code next} is the index past the escape (including the single whitespace delimiter a hex run may carry, a
484	     CRLF pair counting as one delimiter), and {@code codePoint} is the decoded code point. Per the CSS spec a NUL,
485	     surrogate, or out-of-range value becomes U+FFFD; a lone trailing backslash has no escape ({@code codePoint} is
486	     {@code -1}) and is left to the caller as a stray character.
487	     */
488	    private static int[] consumeEscape(String value, int i, int end) {
489	        if (i + 1 >= end) return new int[] {end, -1};
490	        char next = value.charAt(i + 1);
491	        if (isHex(next)) {
492	            int h = i + 1;
493	            int e = h;
494	            while (e < end && e - h < 6 && isHex(value.charAt(e))) e++;
495	            int code = Integer.parseInt(value.substring(h, e), 16);
496	            int after = e;
497	            if (after < end && isCssSpace(value.charAt(after))) {
498	                after++; // the single delimiter whitespace is part of the hex escape
499	                if (after - e == 2 && value.charAt(e) == '\r' && after < end && value.charAt(after) == '\n') after++;
500	            }
501	            if (code == 0 || code > Character.MAX_CODE_POINT
502	                || (code >= Character.MIN_SURROGATE && code <= Character.MAX_SURROGATE))
503	                code = 0xFFFD;
504	            return new int[] {after, code};
505	        }
506	        return new int[] {i + 2, next};
507	    }
508	
509	    /**
510	     Applies the same reference rules to text that is not itself parsed as declarations — the free-form value of a
511	     custom property. As in an ordinary value, quoted strings and comments are inert token separators (a fake call
512	     written inside either never fetches), while every real {@code url(...)} (its name possibly hex- or
513	     character-escaped), {@code @import}, and the legacy {@code expression(...)} function is normalized and checked.
514	     */
515	    private boolean freeTextIsSafe(String text) {
516	        int end = text.length();
517	        int i = 0;
518	        while (i < end) {
519	            char c = text.charAt(i);
520	            if (c == '"' || c == '\'') {
521	                int[] quote = scanQuoted(text, i + 1, c);
522	                if (quote[1] != 1) return false;
523	                if (stringGluesIdentToCall(text, i, quote[0], end)) return false; // e.g. "u"rl(...) or ur"l"(...)
524	                i = quote[0] + 1;
525	                continue;
526	            }
527	            if (c == '/' && i + 1 < end && text.charAt(i + 1) == '*') {
528	                int close = text.indexOf("*/", i + 2);
529	                if (close < 0) return false;
530	                i = close + 2;
531	                continue;
532	            }
533	            if (c == '@') {
534	                StringBuilder atName = new StringBuilder();
535	                int nameEnd = scanIdent(text, i + 1, end, atName);
536	                if (atName.toString().equalsIgnoreCase("import") && !freeTextImportIsSafe(text, nameEnd, end))
537	                    return false;
538	                i = nameEnd > i + 1 ? nameEnd : i + 1;
539	                continue;
540	            }
541	            if (isIdentStart(c) || c == '-' || c == '\\') {
542	                StringBuilder decoded = new StringBuilder();
543	                int nameEnd = scanIdent(text, i, end, decoded);
544	                int j = skipSeparators(text, nameEnd, end);
545	                if (j < 0) return false;
546	                if (commentGluesIdentToCall(text, nameEnd, end)) return false; // e.g. ur/**/l(...)
547	                if (j < end && text.charAt(j) == '(') {
548	                    String fnName = decoded.toString();
549	                    int argEnd = matchingParen(text, j + 1, end);
550	                    if (argEnd < 0) return false;
551	                    if (!isPlainName(fnName)) return false;
552	                    if (fnName.equalsIgnoreCase("expression")) return false;
553	                    if (fnName.equalsIgnoreCase("url") && !isSafeUrlArgument(text, j + 1, argEnd)) return false;
554	                    i = j; // resume at '(' so a nested url()/expression() in the arguments is also checked
555	                    continue;
556	                }
557	                i = nameEnd;
558	                continue;
559	            }
560	            i++;
561	        }
562	        return true;
563	    }
564	
565	    /**
566	     Tests whether a quoted string at {@code [open, close]} is glued without whitespace to identifier runs on
567	     either side and followed by a call: {@code "u"rl(...)}, {@code ur"l"(...)}, or {@code u"rl"(...)}. Such
568	     token sequences are value syntax errors a strict browser discards, but a lenient engine could read the glued
569	     runs as one escaped {@code url} or {@code expression} call, so the declaration is rejected rather than risk a
570	     split name escaping recognition. The adjacent runs are read with full escape semantics. Ordinary tokens
571	     separated from the string by whitespace (such as a real {@code url(...)} later in the value) are unaffected.
572	     */
573	    private boolean stringGluesIdentToCall(String value, int open, int close, int end) {
574	        boolean gluedBefore = open > 0 && isIdentChar(value.charAt(open - 1));
575	        int after = close + 1;
576	        boolean gluedAfter = after < end && (isIdentStart(value.charAt(after)) || value.charAt(after) == '\\');
577	        if (!gluedBefore && !gluedAfter) return false;
578	        int k = after;
579	        if (gluedAfter) {
580	            StringBuilder ignored = new StringBuilder();
581	            k = scanIdent(value, k, end, ignored);
582	        }
583	        k = skipSeparators(value, k, end);
584	        return k >= 0 && k < end && value.charAt(k) == '(';
585	    }
586	
587	    /** Checks the quoted-string or {@code url(...)} reference of an {@code @import} found in free text. */
588	    private boolean freeTextImportIsSafe(String text, int from, int end) {
589	        int i = skipSeparators(text, from, end);
590	        if (i < 0) return false;
591	        if (i >= end) return true; // a dangling "@import" with no reference is inert junk
592	        char c = text.charAt(i);
593	        if (c == '"' || c == '\'') {
594	            int[] quote = scanQuoted(text, i + 1, c);
595	            if (quote[1] != 1) return false;
596	            return safelist.isSafeStyleUrl(tagName, el, unescape(text.substring(i + 1, quote[0])));
597	        }
598	        if (isIdentStart(c) || c == '-' || c == '\\') {
599	            StringBuilder fnName = new StringBuilder();
600	            int nameEnd = scanIdent(text, i, end, fnName);
601	            int k = skipSeparators(text, nameEnd, end);
602	            if (k < 0 || k >= end || text.charAt(k) != '(' || !fnName.toString().equalsIgnoreCase("url")) return false;
603	            int argEnd = matchingParen(text, k + 1, end);
604	            return argEnd >= 0 && isSafeUrlArgument(text, k + 1, argEnd);
605	        }
606	        return false;
607	    }
608	
609	    /** Extracts and validates the single URL argument of a {@code url(...)} function. */
610	    boolean isSafeUrlArgument(String value, int from, int end) {
611	        int i = from;
612	        while (i < end && isCssSpace(value.charAt(i))) i++;
613	        int j = end;
614	        while (j > i && isCssSpace(value.charAt(j - 1))) j--;
615	        if (i == j) return false; // url() with no reference
616	
617	        char first = value.charAt(i);
618	        String raw;
619	        if (first == '"' || first == '\'') {
620	            int[] quote = scanQuoted(value, i + 1, first);
621	            if (quote[1] != 1 || quote[0] + 1 != j) return false; // unterminated or trailing junk inside the quotes
622	            raw = value.substring(i + 1, quote[0]);
623	            for (int k = 0; k < raw.length(); k++) { // the closing quote may not appear inside, escaped or not
624	                char c = raw.charAt(k);
625	                if (c == '\\') { k++; continue; }
626	                if (c == first) return false;
627	            }
628	        } else {
629	            // an unquoted URL token is a single run: a bare quote or whitespace is a syntax error, not part of the
630	            // URL. Whitespace that is the delimiter of a hex escape (or a whitespace character itself escaped) is
631	            // part of the escape and so stays in the run, exactly as a browser reads it.
632	            int k = i;
633	            while (k < j) {
634	                char c = value.charAt(k);
635	                if (c == '\\') {
636	                    int[] escape = consumeEscape(value, k, j);
637	                    if (escape[1] < 0) return false; // a lone trailing backslash is no URL token
638	                    k = escape[0];
639	                    continue;
640	                }
641	                if (c == '"' || c == '\'' || isCssSpace(c)) return false;
642	                k++;
643	            }
644	            raw = value.substring(i, j);
645	        }
646	        return safelist.isSafeStyleUrl(tagName, el, unescape(raw));
647	    }
648	
649	    /** Returns the index of the ')' matching the '(' whose argument starts at {@code from}, or {@code -1}. */
650	    int matchingParen(String value, int from, int end) {
651	        int depth = 1;
652	        int i = from;
653	        while (i < end) {
654	            char c = value.charAt(i);
655	            if (c == '\\') { i += 2; continue; }
656	            if (c == '"' || c == '\'') {
657	                int[] quote = scanQuoted(value, i + 1, c);
658	                if (quote[1] != 1) return -1;
659	                i = quote[0] + 1;
660	                continue;
661	            }
662	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
663	                int close = value.indexOf("*/", i + 2);
664	                if (close < 0 || close >= end) return -1; // an unterminated comment leaves the function unclosed
665	                i = close + 2;
666	                continue;
667	            }
668	            if (c == '(') depth++;
669	            else if (c == ')') { depth--; if (depth == 0) return i; }
670	            i++;
671	        }
672	        return -1;
673	    }
674	
675	    /**
676	     Decodes CSS backslash escapes in a URL token, mirroring how a browser reads the reference: a {@code \}{@code hEX}
677	     run (up to six hex digits, optionally followed by one whitespace delimiter) becomes its code point, and any other
678	     backslash-prefixed character collapses to that character. An obfuscated scheme such as {@code java\73cript:} or
679	     {@code \6a avascript:} therefore cannot hide from the protocol check. A NUL code point is dropped, matching the
680	     CSS requirement to replace it.
681	     */
682	    static String unescape(String value) {
683	        if (value.indexOf('\\') == -1) return value;
684	        int length = value.length();
685	        StringBuilder sb = null;
686	        int i = 0;
687	        while (i < length) {
688	            char c = value.charAt(i);
689	            if (c == '\\' && i + 1 < length) {
690	                if (sb == null) {
691	                    sb = new StringBuilder(length);
692	                    sb.append(value, 0, i);
693	                }
694	                int h = i + 1;
695	                int hexEnd = h;
696	                while (hexEnd < length && hexEnd - h < 6 && isHex(value.charAt(hexEnd))) hexEnd++;
697	                if (hexEnd > h) {
698	                    int code = Integer.parseInt(value.substring(h, hexEnd), 16);
699	                    if (hexEnd < length && isCssSpace(value.charAt(hexEnd))) hexEnd++;
700	                    // per the CSS spec, NUL, surrogates, and values above the Unicode range become U+FFFD
701	                    if (code == 0 || code > Character.MAX_CODE_POINT
702	                        || (code >= Character.MIN_SURROGATE && code <= Character.MAX_SURROGATE))
703	                        code = 0xFFFD;
704	                    sb.appendCodePoint(code);
705	                    i = hexEnd;
706	                } else {
707	                    sb.append(value.charAt(i + 1));
708	                    i += 2;
709	                }
710	                continue;
711	            }
712	            if (sb != null) sb.append(c);
713	            i++;
714	        }
715	        return sb != null ? sb.toString() : value;
716	    }
717	
718	    static boolean isCssSpace(char c) {
719	        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
720	    }
721	
722	    private static boolean isHex(char c) {
723	        return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
724	    }
725	
726	    private static boolean isIdentStart(char c) {
727	        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_';
728	    }
729	
730	    private static boolean isIdentChar(char c) {
731	        return isIdentStart(c) || (c >= '0' && c <= '9') || c == '-';
732	    }
733	}
