245	        int numDiscarded = 0;
246	        Attributes sourceAttrs = sourceEl.attributes();
247	        for (Attribute sourceAttr : sourceAttrs) {
248	            if (safelist.isSafeAttribute(sourceTag, sourceEl, sourceAttr)) { // will keep this attr
249	                String key = sourceAttr.getKey();
250	                String value = sourceAttr.getValue();
251	
252	                if (Safelist.isSrcset(key)) { // clean the srcset candidates; drop the attribute if none survive
253	                    String cleaned = safelist.cleanSrcset(sourceTag, sourceEl, value);
254	                    if (cleaned == null) {
255	                        numDiscarded++;
256	                        continue;
257	                    }
258	                    if (!cleaned.equals(value))
259	                        numDiscarded++; // candidates were dropped or normalized
260	                    value = cleaned;
261	                } else if (Safelist.isStyle(key)) { // clean inline CSS declaration by declaration; drop if none survive
262	                    String cleaned = safelist.cleanStyle(sourceTag, sourceEl, value);
263	                    if (cleaned == null) {
264	                        numDiscarded++;
265	                        continue;
266	                    }
267	                    if (!cleaned.equals(value))
268	                        numDiscarded++; // unsafe or malformed declarations were dropped
269	                    value = cleaned;
270	                } else if (safelist.shouldAbsUrl(sourceTag, key)) { // configured to make absolute urls for this key (href)
271	                    value = sourceEl.absUrl(key);
272	                    if (value.isEmpty()) // could not be made abs; leave as-is to allow custom unknown protocols
273	                        value = sourceAttr.getValue();
274	                }
