12	/**
13	 Tests for rule-by-rule sanitization of an allowed {@code <style>} element's stylesheet text by the {@link Cleaner}
14	 and {@link StyleSheetCleaner}.
15	 */
16	public class StyleSheetCleanerTest {
17	    private static final String Base = "https://example.com/a/b";
18	
19	    private static Safelist sheetSafelist() {
20	        return Safelist.relaxed().addTags("style").addAttributes(":all", "style");
21	    }
22	
23	    private static Document cleanDoc(String html, String baseUri, Safelist safelist) {
24	        return new Cleaner(safelist).clean(Jsoup.parseBodyFragment(html, baseUri));
25	    }
26	
27	    private static String sheet(String css) {
28	        return sheet(css, Base, sheetSafelist());
29	    }
