31	    private static String sheet(String css, String baseUri, Safelist safelist) {
32	        Element style = cleanDoc("<style>" + css + "</style>", baseUri, safelist).selectFirst("style");
33	        return style == null ? null : style.data();
34	    }
35	
36	    private static String body(String css) {
37	        return cleanDoc("<style>" + css + "</style><p>x</p>", Base, sheetSafelist()).body().html();
38	    }
39	
40	    @Test void keepsOrdinaryRulesAndDeclarationsInOrder() {
41	        assertEquals("a { color: red; FONT-SIZE :14px;margin:0} b{color:#fff}",
42	            sheet("a { color: red; FONT-SIZE :14px ;margin:0} b{color:#fff}"));
43	        // selectors, colors, numbers, fonts, and custom properties keep their source spelling
44	        assertEquals("*[data-x]:hover > .a#b + p { --v: calc(1px + var(--y)); font: 12px 'Arial'}",
45	            sheet("*[data-x]:hover > .a#b + p { --v: calc(1px + var(--y)); font: 12px 'Arial' }"));
46	    }
