53	    @Test void dropsOnlyTheDangerousDeclaration() {
54	        assertEquals("a { color: red; margin: 0} b{font:12px 'x;y'}",
55	            sheet("a { color: red; background: url(javascript:1); margin: 0 } b{font:12px 'x;y'}"));
56	        assertEquals("p{color:red;color:blue}",
