60	    @Test void removesStyleElementWhenEveryRuleIsRejected() {
61	        assertNull(sheet("p{background:url(javascript:1)}"));
62	        assertNull(sheet("hello")); // non-CSS text is not a rule
63	        assertEquals("<p>x</p>", org.jsoup.TextUtil.stripNewlines(body("p{background:url(javascript:1)}")));
64	    }
