70	    @Test void policyDisallowingStyleStillRemovesWholeElement() {
71	        String html = "<style>p{color:red}</style><p>x</p>";
72	        Document clean = new Cleaner(Safelist.relaxed()).clean(Jsoup.parseBodyFragment(html, Base));
73	        assertNull(clean.selectFirst("style"));
74	        assertFalse(Jsoup.isValid(html, Safelist.relaxed()));
75	    }
76	
77	    @Test void importReferencesAreChecked() {
78	        assertEquals("@import url(https://example.com/x.css); p{color:red}",
79	            sheet("@import url(https://example.com/x.css); p{color:red}"));
