81	            sheet("@import \"https://example.com/x.css\";p{color:red}"));
82	        // the rejected import alone is removed; the following rule (with its source spacing) is untouched
83	        assertEquals(" p{color:red}", sheet("@import 'javascript:alert(1)'; p{color:red}"));
84	        assertNull(sheet("@import url(javascript:alert(1))"));
