99	        assertEquals("@media screen { p { color:red;} img { width: 1px}}",
100	            sheet("@media screen { p { color:red; background: url(javascript:1) } img { width: 1px } }"));
101	        assertEquals("@supports (display: grid) { p { color:red;}}",
102	            sheet("@supports (display: grid) { p { color:red; background: url(javascript:1) } }"));
