import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.safety.*;

public class Probe {
    static final String Base = "https://example.com/a/b";
    static Safelist sl() { return Safelist.relaxed().addTags("style").addAttributes(":all","style"); }

    static String sheet(String css) {
        Element s = new Cleaner(sl()).clean(Jsoup.parseBodyFragment("<style>"+css+"</style>", Base)).selectFirst("style");
        return s == null ? "<REMOVED>" : "["+s.data().replace("\n","\\n").replace("\r","\\r")+"]";
    }
    static String body(String html, Safelist sl, String base) {
        return new Cleaner(sl).clean(Jsoup.parseBodyFragment(html, base)).body().html().replace("\n","\\n");
    }
    static void t(String label, Object got, Object exp) {
        System.out.println((got.equals(exp)?"OK  ":"FAIL ")+label+"\n     got: "+got+"\n     exp: "+exp);
    }
    public static void main(String[] a) {
        // 1. whitespace/comment-only and empty rules -> spec says DELETE element
        System.out.println("== whitespace / comments / empty rules ==");
        System.out.println("blank:    " + sheet("   "));
        System.out.println("newlines: " + sheet("\n\n  \t"));
        System.out.println("comment:  " + sheet("/* hi */"));
        System.out.println("comments+ws: " + sheet("  /* x */  /* y */ "));
        System.out.println("empty rule a{}: " + sheet("a{}"));
        System.out.println("empty media: " + sheet("@media screen {}"));
        System.out.println("empty rule then safe: " + sheet("a{} p{color:red}"));
        System.out.println("safe then empty rule: " + sheet("p{color:red} a{}"));

        // 2. no orphan text transferred to parent on removal
        System.out.println("== removal serialization ==");
        System.out.println(body("<div><style>p{color:red;background:url(javascript:1)}</style><p>x</p></div>", sl(), Base));
        System.out.println(body("<style>  </style><p>x</p>", sl(), Base));
        System.out.println(body("<style>/*c*/</style><p>x</p>", sl(), Base));
        System.out.println(body("<style>a{}</style><p>x</p>", sl(), Base));

        // 3. disallowed style element -> whole element deletion, attrs too
        System.out.println("== disallowed style tag ==");
        System.out.println(body("<style type=\"text/css\" id=x>p{color:red}</style><p>x</p>", Safelist.relaxed(), Base));

        // 4. attributes on kept style element
        System.out.println("== style element attributes ==");
        Safelist withAttr = sl().addAttributes("style","type","media","id");
        System.out.println(body("<style type=\"text/css\" media=\"screen\" onclick=\"evil()\" id=s>p{color:red}</style><p>x</p>", withAttr, Base));
        // attrs survive when content fully rejected? element removed so attrs removed too
        System.out.println(body("<style type=\"text/css\" id=s>p{background:url(javascript:1)}</style><p>x</p>", withAttr, Base));

        // 5. order stability with multiple styles and normal nodes
        System.out.println("== order ==");
        System.out.println(body("<style>p{color:red}</style><p>1</p><style>b{color:blue}</style><p>2</p>", sl(), Base));
        System.out.println(body("<style>bad</style><p>1</p><style>b{color:blue}</style>", sl(), Base));

        // 6. isolation: input unchanged
        System.out.println("== isolation ==");
        Document d = Jsoup.parseBodyFragment("<style>p{color:red;background:url(javascript:1)}</style>", Base);
        String before = d.body().html();
        new Cleaner(sl()).clean(d);
        System.out.println("input unchanged: " + before.equals(d.body().html()));

        // 7. control char / case / percent bypasses
        System.out.println("== obfuscation ==");
