        Document e = new Cleaner(sl()).clean(Jsoup.parseBodyFragment("<style></style><p>x</p>", Base));
        System.out.println("empty style -> " + e.body().html().replace("\n","\\n"));

        // idempotency fuzz
        String[] atoms = {"a", "p", "*", "@media screen", "@import", "@font-face", "@x",
            "{", "}", ";", "(", ")", "url(x)", "url(javascript:1)", "url(//h/x)", "url(https://example.com/x)",
            "color:red", "background:url(img/x.png)", "--v: 1", "'str", "\"s\"", "/*c*/", "/*c", "\\", "\\75 ",
            " ", "\n", "\t", "###", "::", "expression(1)", "100%", "#fff", "calc(1px)"};
        Random r = new Random(42);
        int trials = 200000, fails = 0;
        for (int t = 0; t < trials; t++) {
            StringBuilder sb = new StringBuilder();
            int n = 1 + r.nextInt(8);
            for (int i = 0; i < n; i++) sb.append(atoms[r.nextInt(atoms.length)]);
            String css = sb.toString();
            String once, twice;
            try { once = clean(css); } catch (Throwable ex) { System.out.println("THROW once: "+ex+" css="+escape(css)); if (++fails>20) return; continue; }
            try { twice = clean(once == null ? "p{}" : once); } catch (Throwable ex) { System.out.println("THROW twice: "+ex+" css="+escape(once)); if (++fails>20) return; continue; }
            String onceExpect = once;
            if (once != null) {
                if (!Objects.equals(once, twice)) {
                    System.out.println("NON-IDEMPOTENT:\n  in :"+escape(css)+"\n  one:"+escape(once)+"\n  two:"+escape(twice));
                    if (++fails > 20) return;
                }
                if (once.toLowerCase().contains("javascript") || once.contains("//cdn")) {
                    System.out.println("LEAK: "+escape(once));
                    if (++fails > 20) return;
                }
            }
        }
        System.out.println("fuzz done, fails="+fails);
    }
    static String escape(String s) {
        StringBuilder b = new StringBuilder("\"");
        for (int i=0;i<s.length();i++){char c=s.charAt(i); if(c=='\\')b.append("\\\\"); else if(c=='"')b.append("\\\""); else if(c=='\n')b.append("\\n"); else if(c=='\r')b.append("\\r"); else if(c=='\t')b.append("\\t"); else if(c<32)b.append("\\x"+(int)c); else b.append(c);}
        return b.append("\"").toString();
    }
}
