import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.*;
public class Probe4 {
    public static void main(String[] a) {
        String base = "https://example.com/a/b";
        Safelist sl = Safelist.relaxed().addTags("style").addAttributes(":all","style").addAttributes("style","type","id");
        String[] htmls = {
            "<style></style><p>x</p>",
            "<style type=\"text/css\" id=s>  \n </style><p>x</p>",
            "<div><style></style></div><p>x</p>",
        };
        for (String h: htmls) {
            Document once = new Cleaner(sl).clean(Jsoup.parseBodyFragment(h, base));
            Document twice = new Cleaner(sl).clean(once);
            String o = once.body().html().replace("\n","\\n"), t = twice.body().html().replace("\n","\\n");
            System.out.println("once: "+o);
            System.out.println("idem: "+o.equals(t)+" | isValid="+Cleaner.isValid(h, sl));
            System.out.println("input intact: "+Jsoup.parseBodyFragment(h, base).body().html().replace("\n","\\n").equals(Jsoup.parseBodyFragment(h, base).body().html()));
        }
    }
}
